#include "s61_binary_univariate_field_20261102.hpp"
#include <flint/fmpq_vec.h>
#include <chrono>
int main(int argc,char**argv){assert(argc==7);ifstream mi(argv[1]),di(argv[2]);string prefix=argv[3];int bound=stoi(argv[4]),nf=stoi(argv[5]);ofstream out(argv[6]);int nr,n;mi>>nr>>n;vector<URow>A(nr);for(auto&r:A){int cnt;mi>>cnt;for(int k=0;k<cnt;k++){int j;URat v;mi>>j;uread(mi,v.n);r.emplace(j,std::move(v));}}URat D;uread(di,D.n);vector<int>anchors;for(int a=0;a<nf;a++){ifstream f(prefix+".k"+to_string(a));int nn,N,anchor;f>>nn>>N>>anchor;assert(nn==n&&N>=bound+3);anchors.push_back(anchor);}out<<n<<' '<<bound<<' '<<nf<<'\n';int use=bound+1,check=use+2;auto start=chrono::steady_clock::now();fmpq_t c,dv,value;for(auto q:{c,dv,value})fmpq_init(q);fmpz_t den,integer,common,g;for(auto p:{den,integer,common,g})fmpz_init(p);fmpq*xs=_fmpq_vec_init(check);fmpq*ys=_fmpq_vec_init(check*n);fmpq*target=_fmpq_vec_init(use);
 for(int a=0;a<nf;a++){
  ifstream si(prefix+".k"+to_string(a));int nn,N,anchor;si>>nn>>N>>anchor;assert(nn==n&&anchor==anchors[a]);for(int i=0;i<check;i++){long x;string ds;si>>x>>ds;fmpq_set_si(xs+i,x,1);assert(fmpz_set_str(den,ds.c_str(),10)==0);fmpq_poly_evaluate_fmpq(dv,D.n,xs+i);assert(!fmpq_is_zero(dv));for(int j=0;j<n;j++){string z;si>>z;assert(fmpz_set_str(fmpq_numref(c),z.c_str(),10)==0);fmpz_set(fmpq_denref(c),den);fmpq_canonicalise(c);fmpq_mul(ys+i*n+j,c,dv);}}
  vector<URat>V(n);for(int j=0;j<n;j++){for(int i=0;i<use;i++)fmpq_set(target+i,ys+i*n+j);assert(fmpq_poly_interpolate_fmpq_vec(V[j].n,xs,target,use));for(int i=use;i<check;i++){fmpq_poly_evaluate_fmpq(value,V[j].n,xs+i);assert(fmpq_equal(value,ys+i*n+j));}}
  for(int b=0;b<nf;b++)if(b==a)assert(fmpq_poly_equal(V[anchors[b]].n,D.n));else assert(V[anchors[b]].zero());cerr<<"INTERPOLATED "<<a<<" SEC "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<'\n';
  URat tmp,sum;for(int i=0;i<nr;i++){fmpq_poly_zero(sum.n);for(auto&[j,v]:A[i])if(!V[j].zero()){fmpq_poly_mul(tmp.n,v.n,V[j].n);fmpq_poly_add(sum.n,sum.n,tmp.n);}assert(sum.zero());}
  fmpz_one(common);for(auto&v:V)fmpz_lcm(common,common,fmpq_poly_denref(v.n));fmpz_zero(g);int count=0;for(auto&v:V)for(int k=0;k<fmpq_poly_length(v.n);k++){fmpq_poly_get_coeff_fmpq(c,v.n,k);if(fmpq_is_zero(c))continue;count++;fmpz_divexact(integer,common,fmpq_denref(c));fmpz_mul(integer,integer,fmpq_numref(c));fmpz_gcd(g,g,integer);}out<<count;int maxbits=0;for(int k=0;k<=bound;k++)for(int j=0;j<n;j++){fmpq_poly_get_coeff_fmpq(c,V[j].n,k);if(fmpq_is_zero(c))continue;fmpz_divexact(integer,common,fmpq_denref(c));fmpz_mul(integer,integer,fmpq_numref(c));fmpz_divexact(integer,integer,g);maxbits=max(maxbits,int(fmpz_bits(integer)));char*s=fmpz_get_str(nullptr,10,integer);out<<' '<<k*n+j<<' '<<s;flint_free(s);}out<<'\n';out.flush();cerr<<"EXACT_FULL_POLYNOMIAL_KERNEL "<<a<<" TERMS "<<count<<" BITS "<<maxbits<<" SEC "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<'\n';
 }
 _fmpq_vec_clear(xs,check);_fmpq_vec_clear(ys,check*n);_fmpq_vec_clear(target,use);for(auto p:{den,integer,common,g})fmpz_clear(p);for(auto q:{c,dv,value})fmpq_clear(q);flint_cleanup();}
